import { readFileSync } from "fs";
import { join } from "path";

import test from "ava";

import { extractTextPerPage, layoutPerPage, layoutPerPageAsync, PdfDown } from "../index";
import type { PageLayout, TextWord } from "../index";

// ── Fixtures ─────────────────────────────────────────────────────────────────

// Generated by `cargo run --example gen_fixtures`; see `layout_sample` there for
// the content stream, which paints the footer first and the title second.
const sample = readFileSync(join(import.meta.dirname, "fixtures", "layout", "layout-sample.pdf"));
const imageOnly = readFileSync(join(import.meta.dirname, "fixtures", "ascii85-dct-scan.pdf"));
const fontsSample = readFileSync(join(import.meta.dirname, "fixtures", "layout", "fonts-sample.pdf"));
const PUBLIC = join(import.meta.dirname, "fixtures", "invoices");
const wordpress = readFileSync(join(PUBLIC, "wordpress-pdf-invoice-plugin-sample.pdf"));
const addOnSamples = readFileSync(join(PUBLIC, "Downloadable-PDF-Invoices-Add-On-Samples.pdf"));

const near = (actual: number, expected: number, tolerance = 0.01) => Math.abs(actual - expected) <= tolerance;

const lineTexts = (page: PageLayout) => page.lines.map((l) => l.text);

const wordNamed = (page: PageLayout, text: string): TextWord => {
  const w = page.words.find((x) => x.text === text);
  if (!w) throw new Error(`no word "${text}" on page ${page.page}`);
  return w;
};

/** Every line addresses a contiguous run of words that point back at it, and its text is those words joined. */
const assertLineIndexConsistent = (t: { true: (v: boolean, m?: string) => void }, page: PageLayout) => {
  let expectedFirst = 0;
  for (const [i, line] of page.lines.entries()) {
    t.true(line.firstWord === expectedFirst, `page ${page.page} line ${i}: firstWord is contiguous`);
    const slice = page.words.slice(line.firstWord, line.firstWord + line.wordCount);
    t.true(slice.length === line.wordCount, `page ${page.page} line ${i}: wordCount in range`);
    t.true(
      slice.every((w) => w.line === i),
      `page ${page.page} line ${i}: words point back at it`
    );
    t.true(slice.map((w) => w.text).join(" ") === line.text, `page ${page.page} line ${i}: text is the joined words`);
    expectedFirst += line.wordCount;
  }
  t.true(expectedFirst === page.words.length, `page ${page.page}: lines cover every word`);
};

const assertTopToBottom = (t: { true: (v: boolean, m?: string) => void }, page: PageLayout) => {
  for (let i = 1; i < page.lines.length; i++) {
    t.true(page.lines[i].y1 <= page.lines[i - 1].y1 + 0.5, `page ${page.page}: line ${i} is not above line ${i - 1}`);
  }
};

// ── Generated fixture: exact geometry ────────────────────────────────────────

test("layout-sample: reading order ignores content-stream order", (t) => {
  const [p1] = layoutPerPage(sample);
  t.is(p1.page, 1);
  t.is(p1.source, "Native");
  t.deepEqual([p1.width, p1.height, p1.rotate], [612, 792, 0]);
  t.deepEqual(lineTexts(p1), [
    "Layout Sample",
    "Item Qty Amount",
    "Widget 2 10,00",
    "Gadget 5 25,00",
    "Word spacing applies here",
    "Inside a form XObject",
    "Page 1 of 2"
  ]);
  t.deepEqual(p1.warnings, []);
  assertLineIndexConsistent(t, p1);
});

test("layout-sample: boxes follow Helvetica metrics, font size and style", (t) => {
  const [p1] = layoutPerPage(sample);
  const title = wordNamed(p1, "Layout");
  t.is(title.fontName, "Helvetica-Bold");
  t.is(title.bold, true);
  t.is(title.italic, false);
  t.is(title.fontSize, 18);
  t.is(title.x0, 50);
  // L a y o u t in Helvetica-Bold: 611+556+556+611+611+333 = 3278 /1000 × 18
  t.true(near(title.x1, 50 + 3.278 * 18), `title x1 ${title.x1}`);
  t.true(near(title.y0, 740 - 0.207 * 18), `title y0 ${title.y0}`);
  t.true(near(title.y1, 740 + 0.718 * 18), `title y1 ${title.y1}`);

  const body = wordNamed(p1, "Gadget");
  t.is(body.fontName, "Helvetica");
  t.is(body.bold, false);
  t.is(body.fontSize, 10);
});

test("layout-sample: table columns share x anchors across rows", (t) => {
  const [p1] = layoutPerPage(sample);
  const qtyColumn = ["Qty", "2", "5"].map((s) => wordNamed(p1, s).x0);
  const amountColumn = ["Amount", "10,00", "25,00"].map((s) => wordNamed(p1, s).x0);
  t.deepEqual(qtyColumn, [300, 300, 300]);
  t.deepEqual(amountColumn, [450, 450, 450]);
  // A TJ kerning adjustment inside "Widget" does not split the word.
  t.is(wordNamed(p1, "Widget").line, 2);
});

test("layout-sample: Tw word spacing widens gaps without merging words", (t) => {
  const [p1] = layoutPerPage(sample);
  const word = wordNamed(p1, "Word");
  const spacing = wordNamed(p1, "spacing");
  // space glyph 278/1000 × 10 + Tw 2
  t.true(near(spacing.x0 - word.x1, 2.78 + 2), `gap ${spacing.x0 - word.x1}`);
});

test("layout-sample: form XObject text goes through /Matrix and cm; images report their placement", (t) => {
  const [p1] = layoutPerPage(sample);
  const inside = wordNamed(p1, "Inside");
  t.is(inside.x0, 320, "cm 300 + Matrix 20");
  t.is(inside.fontSize, 11);
  t.true(near(inside.y0, 410 - 0.207 * 11), `baseline 400 + 10, y0 ${inside.y0}`);
  t.deepEqual(p1.images, [{ xobjectName: "Im1", x0: 400, y0: 650, x1: 500, y1: 700 }]);
});

test("layout-sample: /Rotate is reported, CropBox sizes the page, coordinates stay in user space", (t) => {
  const pages = layoutPerPage(sample);
  t.is(pages.length, 2);
  const p2 = pages[1];
  t.deepEqual([p2.page, p2.width, p2.height, p2.rotate], [2, 300, 500, 90]);
  t.deepEqual(lineTexts(p2), ["Rotated page"]);
  t.is(wordNamed(p2, "Rotated").x0, 20);
  t.is(p2.images.length, 0);
});

test("layout-sample: async and PdfDown match the standalone result", async (t) => {
  const sync = layoutPerPage(sample);
  const pdf = new PdfDown(sample);
  t.deepEqual(await layoutPerPageAsync(sample), sync);
  t.deepEqual(pdf.layout(), sync);
  t.deepEqual(await pdf.layoutAsync(), sync);
});

// ── Image-only and public PDFs ───────────────────────────────────────────────

test("image-only page: no words, the scan's placement is reported, source stays Native", (t) => {
  const [p1] = layoutPerPage(imageOnly);
  t.is(p1.source, "Native");
  t.is(p1.words.length, 0);
  t.is(p1.lines.length, 0);
  t.is(p1.images.length, 1);
  t.true(p1.images[0].x1 > p1.images[0].x0 && p1.images[0].y1 > p1.images[0].y0);
});

test("wordpress sample invoice: lines are top-to-bottom and every word sits on the page", (t) => {
  const [p1] = layoutPerPage(wordpress);
  t.is(p1.lines[0].text, "Invoice");
  t.true(lineTexts(p1).includes("Total Due $93.50"));
  assertTopToBottom(t, p1);
  assertLineIndexConsistent(t, p1);
  for (const w of p1.words) {
    t.true(w.x0 >= 0 && w.x1 <= p1.width && w.y0 >= 0 && w.y1 <= p1.height, `"${w.text}" inside the page`);
    t.true(w.x1 > w.x0 && w.y1 > w.y0, `"${w.text}" has a positive box`);
    t.truthy(w.fontName, `"${w.text}" carries a font name`);
    t.is(w.confidence, undefined, "native words have no OCR confidence");
  }
});

test("add-on samples: every page lays out, images are counted per page", (t) => {
  const pages = layoutPerPage(addOnSamples);
  t.true(pages.length >= 1);
  t.is(pages[0].images.length, 2);
  for (const p of pages) {
    t.true(p.words.length > 0, `page ${p.page} has words`);
    assertTopToBottom(t, p);
    assertLineIndexConsistent(t, p);
  }
});

test("layout costs the same order as plain text extraction", (t) => {
  const runs = 20;
  const t0 = performance.now();
  for (let i = 0; i < runs; i++) layoutPerPage(addOnSamples);
  const layoutMs = (performance.now() - t0) / runs;
  const t1 = performance.now();
  for (let i = 0; i < runs; i++) extractTextPerPage(addOnSamples);
  const textMs = (performance.now() - t1) / runs;
  t.log(`layoutPerPage ${layoutMs.toFixed(2)} ms/doc vs extractTextPerPage ${textMs.toFixed(2)} ms/doc`);
  t.true(layoutMs < 250, "layout stays interactive on a small invoice");
});

test("rejects data that is not a PDF", (t) => {
  t.throws(() => layoutPerPage(Buffer.from("not a pdf")));
});

// ── Fonts that say nothing, or something other than letters ──────────────────

test("fonts-sample: barcode glyphs are flagged symbolic, anonymous fonts carry no weight", (t) => {
  const [p1] = layoutPerPage(fontsSample);
  const byFont = (name: string) => p1.words.filter((w) => w.fontName === name);
  const barcode = byFont("IDAutomationHC39M");
  t.true(barcode.length >= 1, "barcode words present");
  t.true(
    barcode.every((w) => w.symbolic === true),
    "barcode words are symbolic"
  );
  t.true(
    barcode.every((w) => w.bold === false),
    "a named regular font has a known weight"
  );
  const anonymous = byFont("CIDFont+F1");
  t.is(anonymous.length, 2);
  t.true(
    anonymous.every((w) => w.symbolic === false && w.bold === undefined && w.italic === undefined),
    JSON.stringify(anonymous[0])
  );
  const bold = byFont("Helvetica-Bold");
  t.is(bold.length, 2);
  t.true(bold.every((w) => w.bold === true && w.symbolic === false));
});
